def add(id, old, new, rationale, evidence):
    assert s.count(old)==1, (id,s.count(old))
    # Scientific prose is identical across the masters. Description-free figure
    # blocks are recorded separately where the venue differs.
    item=dict(id=id,old=old,new=new,rationale=rationale,retained_evidence=evidence)
    if l.count(old)!=1:
        alternative=re.sub(r'\\Description\{[^\n]*\}\n','',old)
        assert l.count(alternative)==1, (id,l.count(old),l.count(alternative))
        item['old_lncs']=alternative
        item['new_lncs']=re.sub(r'\\Description\{[^\n]*\}\n','',new)
    proposals.append(item)
def block(start,end):
    a=s.index(start); b=s.index(end,a);return s[a:b].rstrip()
